function makeChoiceId(puzzleId, i) { return `${puzzleId}-c${i+1}`; }
window.STARTER_PUZZLES = CURATED_RAW.map(p => {
  const choices = p.choices.map((c,i) => ({
    id: makeChoiceId(p.id,i),
    name: c.name,
    value: c.value || '',
    wiki: c.wiki || '',
    image: ''
  }));
  const answerIndex = p.choices.findIndex(c => c.name === p.answer);
  return {
    id:p.id, category:p.category, title:p.title,
    questionTop:p.questionTop, questionHighlight:p.questionHighlight, questionBottom:p.questionBottom,
    fact:p.fact, choices, answerId:choices[answerIndex].id
  };
});
